import { Object3D, PlaneGeometry, Mesh, Color, Vector2 } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, uvTransform, uv } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextNode } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 * @property {string} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three').Texture} textureLoader
 * @property {Object.<string, Function>} primitives
 * @property {import('three').Camera} camera
 * @property {any} fontAtlas
 */

/**
 * Creates a sprite‑style collection label node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  // Root container
  const root = new Object3D();
  root.position.set(...config.position);
  root.rotation.set(...config.rotation);
  root.scale.set(...config.scale);

  // -----------------------------------------------------------------
  // 1️⃣ Textured plane (sprite) ------------------------------------------------
  // -----------------------------------------------------------------
  // Atlas region (0,0,512,320) – compute normalized UV transform.
  const region = { x: 0, y: 0, w: 512, h: 320 };
  // Assume the source texture size equals the region size if nothing else is known.
  const uvOffset = new Vector2(region.x / region.w, region.y / region.h);
  const uvScale = new Vector2(region.w / region.w, region.h / region.h); // (1,1)

  // Aspect ratio based geometry
  const aspect = region.w / region.h;
  const height = 1; // 1 scene‑unit tall
  const width = height * aspect;
  const planeGeo = new PlaneGeometry(width, height);

  // Load texture
  const tex = ctx.textureLoader(config.assets.imageUrl);
  tex.needsUpdate = true;
  tex.minFilter = tex.magFilter = tex.type === undefined ? undefined : undefined; // keep defaults

  // Node material with UV transform
  const uvNode = uvTransform(uv(), uvOffset, uvScale);
  const mat = new MeshBasicNodeMaterial({
    map: texture(tex).uv(uvNode),
    transparent: true,
    depthWrite: false,
    toneMapped: false,
  });

  const spriteMesh = new Mesh(planeGeo, mat);
  spriteMesh.renderOrder = 1;
  root.add(spriteMesh);

  // -----------------------------------------------------------------
  // 2️⃣ MSDF text overlay ----------------------------------------------------
  // -----------------------------------------------------------------
  const textNode = createTextNode({
    text: config.textContent,
    atlas: ctx.fontAtlas,
    color: new Color('#16161d'), // ink
    size: 0.34, // headline scene‑unit height
    align: 'center',
  });

  // Position text slightly in front of the sprite to avoid z‑fighting
  textNode.position.set(0, 0, 0.001);
  root.add(textNode);

  // -----------------------------------------------------------------
  // 3️⃣ Billboard behaviour -------------------------------------------------
  // -----------------------------------------------------------------
  const updateHandler = () => {
    // Make the sprite always face the camera (simple billboard)
    root.quaternion.copy(ctx.camera.quaternion);
  };
  root.userData.handlers = { update: updateHandler };

  // -----------------------------------------------------------------
  // 4️⃣ Cleanup ------------------------------------------------------------
  // -----------------------------------------------------------------
  const timelines = []; // none in this node but kept for pattern
  root.userData.cleanup = () => {
    // Dispose of geometry & material
    planeGeo.dispose();
    mat.dispose();
    tex.dispose();

    // Dispose text resources if method exists
    if (textNode && typeof textNode.dispose === 'function') {
      textNode.dispose();
    }

    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());
    root.userData.handlers = {};
  };

  return root;
}
